# -*- coding: utf-8 -*-
from qx import X, TF
D = lambda v, e: (v, e)
DET_TOOLEY = [
 D("Tooley 14.4.2: nhiễu tuần hoàn lặp liên tục, nhiễu không tuần hoàn dự đoán được nhưng không liên tục (ví dụ xung đóng cắt), nhiễu ngẫu nhiên hoàn toàn không dự đoán được. Chữ a-periodic nghĩa là không có chu kỳ đều.\nThang: tuần hoàn > không tuần hoàn > ngẫu nhiên về độ dự đoán.",
   "Tooley 14.4.2: periodic noise repeats continuously, aperiodic noise is predictable but not continuous (for example switching pulses), random noise is totally unpredictable. A-periodic means no regular period.\nScale of predictability: periodic > aperiodic > random."),
 D("EMI truyền theo hai đường: dẫn điện qua dây và kết cấu kim loại, hoặc bức xạ qua không khí, nhựa, sợi thuỷ tinh. Phương án chỉ một đường bỏ sót đường còn lại, nên cả hai biện pháp cách ly (che chắn và lọc) đều cần.\nDẫn điện: lọc; bức xạ: che chắn.",
   "EMI travels by two routes: conduction through wiring and metallic structure, or radiation through air, plastic and fibreglass. The one-route options miss the other, so both countermeasures (screening and filtering) are needed.\nConducted: filter; radiated: screen."),
 D("Máy phân tích phổ vẽ biên độ (mức tín hiệu) theo tần số, nên thấy được từng thành phần nhiễu. Dao động ký mới vẽ biên độ theo thời gian. Không có thiết bị nào cho tần số theo thời gian như một đường đơn giản (đó là spectrogram).\nTrục ngang: tần số.",
   "A spectrum analyser plots amplitude (signal level) against frequency, so each noise component can be seen. An oscilloscope plots amplitude against time. No simple instrument plots frequency against time (that is a spectrogram).\nHorizontal axis: frequency."),
 D("Ba nhóm biện pháp giảm EMI là che chắn, liên kết/nối đất và lọc. Chỉ dùng một hay hai nhóm là không đầy đủ vì mỗi nhóm xử lý một đường truyền khác nhau.\nSlide bài giảng cũng nêu thêm tách cáp và lõi ferrite.",
   "The three EMI countermeasure groups are screening, bonding/grounding and filtering. Using only one or two is incomplete because each handles a different path.\nThe lecture slides also add cable separation and ferrite cores."),
 D("HIRF được giảm bằng cùng bộ ba: che chắn, liên kết và lọc. Liên kết cho đường dòng điện trở kháng thấp, che chắn giữ trường ngoài khỏi dây, lọc loại bỏ phần lọt vào.\nHIRF = trường RF cường độ cao từ bên ngoài.",
   "HIRF is reduced by the same trio: screening, bonding and filtering. Bonding provides a low-impedance current path, screening keeps the external field off the wiring, filtering removes what gets in.\nHIRF = high-intensity radiated fields from outside."),
 D("Điện trở liên kết phải cực nhỏ (cỡ mili-ôm) để dòng sét và tĩnh điện chảy qua mà không tạo chênh lệch điện thế. Chỉ phương án \"dưới 0,005 Ω\" nằm trong khoảng hợp lý; hai phương án kia cho điện trở lớn hơn nhiều.\nCảnh báo: Tooley và bài giảng nêu ngưỡng khác nhau (0,001 đến 0,003 Ω) nên chỉ dùng mức độ lớn.",
   "Bonding resistance must be tiny (milliohm order) so lightning and static current flows without creating a potential difference. Only \"below 0.005 Ω\" is in a reasonable range; the other two give far larger resistances.\nWarning: Tooley and the lecture quote different thresholds (0.001 to 0.003 Ω), so use only the order of magnitude."),
 D("Phải liên kết mọi phần kết cấu kim loại với đất để có đường trở kháng thấp cho dòng sét và phóng tĩnh điện; vật dẫn bị cô lập có thể tích điện và phóng tia lửa. Cách điện cáp không giải quyết đường dòng điện.\nQuy tắc: không để vật dẫn \"nổi\".",
   "All parts of the metal structure must be bonded to ground so there is a low-impedance path for lightning and static discharge current; an isolated conductor can charge up and spark. Cable insulation does not provide a current path.\nRule: no \"floating\" conductors."),
 D("Nguồn cấp là DC hoặc 400 Hz (tần số thấp) còn nhiễu theo nguồn ở tần số cao, nên bộ lọc thông thấp giữ nguồn và chặn nhiễu. Bộ thông cao và thông dải sẽ chặn nguồn.\nTần cắt RC: f = 1/(2πRC), ví dụ 1 kΩ và 100 nF cho 1,59 kHz.",
   "The supply is DC or 400 Hz (low frequency) while supply-borne noise is high frequency, so a low-pass filter keeps the supply and blocks the noise. High-pass and band-pass filters would block the supply.\nRC cutoff: f = 1/(2πRC), for example 1 kΩ and 100 nF gives 1.59 kHz."),
 D("Phát xạ mạnh nhất khi mức tín hiệu thay đổi nhiều và nhanh: đóng cắt nhanh với dòng lớn cho di/dt cao. Đóng cắt chậm hay dòng nhỏ đều làm giảm phát xạ.\nChống: làm chậm cạnh xung, dùng tụ hay mạch snubber.",
   "Emission is strongest when the signal level changes a lot and fast: fast switching with a large current gives a high di/dt. Slow switching or small current both reduce emission.\nCountermeasures: slow the edges, use capacitors or a snubber."),
]
DET_FLOYD = [
 D("Hai dây trong cặp xoắn cắt nhau gần 90° nên trường điện từ do tín hiệu của từng dây triệt tiêu, giảm crosstalk. Dây trần hoặc chỉ cách điện dày không làm triệt tiêu trường.\nSelf-Test 1 ở Module 08 hỏi cùng ý.",
   "The two wires of a twisted pair cross at nearly 90° so the fields from each wire's signal cancel, reducing crosstalk. Bare wire or thick insulation alone does not cancel fields.\nSelf-Test 1 in Module 08 asks the same thing."),
 D("STP có vỏ kim loại bao quanh nên bảo vệ tốt hơn trước EMI nhưng đắt và nặng hơn UTP. UTP dùng ở môi trường ít nhiễu và tần số thấp hơn (đến khoảng 1 MHz).\nChọn: nhiễu cao thì STP, ít nhiễu thì UTP.",
   "STP has a surrounding metal sleeve so it protects better against EMI but is costlier and heavier than UTP. UTP suits low-noise environments and lower frequencies (up to about 1 MHz).\nChoose: high noise STP, low noise UTP."),
 D("Mạch số chuyển mạch nhanh rút dòng xung từ nguồn nên VCC bị gai. Tụ tách nối VCC xuống đất cung cấp dòng cục bộ và hấp thụ gai; đặt gần chân nguồn của IC. Tăng điện trở nguồn làm gai tệ hơn.\nPhối hợp: tụ khối 1 µF + tụ nhỏ 0,022 đến 0,1 µF.",
   "Fast-switching digital circuits draw pulses of current from the supply so VCC spikes. A decoupling capacitor from VCC to ground supplies local current and absorbs the spikes; place it close to the IC power pin. Raising the supply resistance makes spikes worse.\nCombine: a 1 µF bulk capacitor with 0.022 to 0.1 µF small ones."),
 D("Noise margin mức cao V_NH = V_OH(min) − V_IH(min): phần dư giữa mức cao tối thiểu mà cổng lái đưa ra và mức cao tối thiểu mà cổng nhận chấp nhận. Mức thấp là V_NL = V_IL(max) − V_OL(max). Hai phương án còn lại trộn các đại lượng sai.\nNhớ: lấy đầu ra trừ đầu vào ở cùng mức.",
   "The high-level noise margin V_NH = V_OH(min) − V_IH(min): the margin between the minimum high that the driving gate delivers and the minimum high the receiving gate accepts. The low level is V_NL = V_IL(max) − V_OL(max). The other options mix the wrong quantities.\nRemember: output minus input at the same level."),
 D("V_NH = V_OH(min) − V_IH(min) = 2,4 − 2,25 = 0,15 V; V_NL = V_IL(max) − V_OL(max) = 0,65 − 0,4 = 0,25 V. 2,4 V và 0,4 V chỉ là mức đầu ra, không phải noise margin.\nNoise margin nhỏ nghĩa là dễ bị nhiễu làm đổi mức.",
   "V_NH = V_OH(min) − V_IH(min) = 2.4 − 2.25 = 0.15 V; V_NL = V_IL(max) − V_OL(max) = 0.65 − 0.4 = 0.25 V. 2.4 V and 0.4 V are just output levels, not noise margins.\nA small noise margin means noise can flip the level easily."),
]
DET_GEN = [
 D("10 log(0,5 W/1 mW) = 10 log 500 = 26,99, xấp xỉ 27 dBm. 30 dBm là 1 W và −3 dBm là nửa mW. Mốc nhớ: 0 dBm = 1 mW, 30 dBm = 1 W.\nĐổi nhanh: mỗi ×10 công suất là +10 dB.",
   "10 log(0.5 W/1 mW) = 10 log 500 = 26.99, about 27 dBm. 30 dBm is 1 W and −3 dBm is half a mW. Anchors: 0 dBm = 1 mW, 30 dBm = 1 W.\nQuick rule: each ×10 of power is +10 dB."),
 D("Với điện áp: V_out = V_in × 10^(dB/20) = 10^(−0,1) = 0,794 V. 0,631 là kết quả nếu dùng 10 thay 20 (tính theo công suất).\nĐiện áp dùng 20 log, công suất dùng 10 log.",
   "For voltage: V_out = V_in × 10^(dB/20) = 10^(−0.1) = 0.794 V. 0.631 results from using 10 instead of 20 (the power formula).\nVoltage uses 20 log, power uses 10 log."),
 D("+40 dB công suất là ×10⁴, 10 W × 10 000 = 100 kW. Slide 21 in 10 kW là sai (thiếu một bậc 10). 400 W nhầm cộng thành nhân.\nKiểm tra: +10 dB ×10, +20 dB ×100, +30 dB ×1000, +40 dB ×10⁴.",
   "+40 dB in power is ×10⁴, 10 W × 10,000 = 100 kW. Slide 21's 10 kW is wrong (off by a factor of 10). 400 W confuses adding with multiplying.\nCheck: +10 dB ×10, +20 dB ×100, +30 dB ×1000, +40 dB ×10⁴."),
 D("Mức dBm cộng trực tiếp với độ lợi dB: −20 + 30 = +10 dBm = 10 mW. −50 dBm là trừ nhầm và 30 dBm là bỏ mức vào.\nKhông cộng dBm với dBm; chỉ cộng dBm với dB.",
   "A dBm level adds directly to a dB gain: −20 + 30 = +10 dBm = 10 mW. −50 dBm subtracts by mistake and 30 dBm ignores the input level.\nDo not add dBm to dBm; only dBm plus dB."),
 D("Điện áp tăng ×10 cho 20 log 10 = +20 dB. Công suất ×10 mới là +10 dB. +100 dB là ×10⁵ về điện áp.\nBình phương: công suất ∝ V², nên hệ số 20 gấp hai lần hệ số 10.",
   "A tenfold voltage increase gives 20 log 10 = +20 dB. A tenfold power increase is +10 dB. +100 dB is ×10⁵ in voltage.\nSquaring: power ∝ V², so the factor 20 is double the factor 10."),
 D("Sóng vuông chỉ có hài lẻ với biên độ V/n (theo cách đặt của Tooley, V là biên độ cơ bản). Hài 5: 50/5 = 10 V ở 5 × 2 kHz = 10 kHz. 5 kHz nhầm tần số thành chia.\nHài chẵn của sóng vuông đối xứng bằng 0.",
   "A square wave has only odd harmonics with amplitude V/n (in Tooley's form, V is the fundamental amplitude). Fifth harmonic: 50/5 = 10 V at 5 × 2 kHz = 10 kHz. 5 kHz divides the frequency by mistake.\nEven harmonics of a symmetric square wave are zero."),
 D("f_r = 1/(2π√(LC)) = 1/(2π√(10 nH × 100 nF)) = 1/(2π × 3,16×10⁻⁸) = 5,03 MHz. 50 kHz và 500 MHz sai số bậc 100.\nESL càng nhỏ, cộng hưởng càng cao, nên tụ nhỏ dùng cho tần số cao.",
   "f_r = 1/(2π√(LC)) = 1/(2π√(10 nH × 100 nF)) = 1/(2π × 3.16×10⁻⁸) = 5.03 MHz. 50 kHz and 500 MHz are off by a factor of 100.\nThe smaller the ESL, the higher the resonance, so small capacitors serve high frequencies."),
 D("Dưới f_r tụ thực là tụ; trên f_r điện cảm ký sinh ESL chiếm ưu thế nên Z = ωL tăng theo tần số và tụ hoạt động như cuộn cảm, kém tác dụng lọc. Nó không bao giờ thành điện trở thuần ở dải rộng.\nVì thế dùng song song tụ lớn và tụ nhỏ.",
   "Below f_r a real capacitor is a capacitor; above f_r the parasitic inductance ESL dominates so Z = ωL rises with frequency and the capacitor acts as an inductor, a poor filter. It never becomes a pure resistor over a wide band.\nThat is why a large and a small capacitor are used in parallel."),
 D("DO-160 là quy trình thử môi trường (gồm EMC) do RTCA ban hành, chính nó không đặt yêu cầu; yêu cầu đến từ quy định chứng nhận. Chuẩn phần mềm là DO-178.\nBa chuẩn: DO-160 (thử), DO-178 (phần mềm), DO-254 (phần cứng).",
   "DO-160 is an environmental (including EMC) test procedure published by the RTCA; it does not set requirements itself, those come from certification rules. The software standard is DO-178.\nThree standards: DO-160 (test), DO-178 (software), DO-254 (hardware)."),
 D("CISPR 11 Nhóm 1 Class A, đo ở 30 m: 30 dBµV/m cho 30 đến 230 MHz và 37 dBµV/m trên 230 MHz. 47 dBµV/m là ngưỡng khác (đo ở khoảng cách khác).\nĐọc kỹ khoảng cách đo khi so ngưỡng.",
   "CISPR 11 Group 1 Class A, measured at 30 m: 30 dBµV/m for 30 to 230 MHz and 37 dBµV/m above 230 MHz. 47 dBµV/m is a different limit (another measuring distance).\nCheck the measuring distance when comparing limits."),
 D("Trên Boeing 757 thiết bị Wi-Fi gây nhiễu màn hình, nên biển trong buồng lái cấm dùng Wi-Fi khi động cơ chạy cho mục đích bay. Ferrite là biện pháp kỹ thuật khác, không phải nội dung biển.\nVí dụ điển hình cho EMI từ thiết bị cá nhân.",
   "On the Boeing 757, Wi-Fi devices interfered with the displays, so the cockpit placard bans Wi-Fi while the engines run for flight purposes. Ferrite is a different technical fix, not the placard's content.\nA typical example of EMI from personal devices."),
 D("Hai dây tín hiệu mang dòng ngược chiều nên từ thông trong lõi ferrite triệt tiêu: trở kháng thấp, tín hiệu không bị cản. Nhiễu chế độ chung có dòng cùng chiều nên từ thông cộng, trở kháng cao, bị chặn.\nFerrite lọc nhiễu chế độ chung mà không ảnh hưởng tín hiệu.",
   "The two signal wires carry opposite currents so the flux in the ferrite cancels: low impedance, the signal is unimpeded. Common-mode noise has same-direction currents so the flux adds, high impedance, it is blocked.\nFerrite filters common-mode noise without affecting the signal."),
]
